    subtitle: `${GITHUB_COMMANDS.length} commandes : auth, repo, PR, issues, releases, CI.`,
    icon: <GithubIcon size={20} />,
    gradient: "from-zinc-700 to-zinc-900",
    accent: "text-zinc-700 dark:text-zinc-300",
    commands: GITHUB_COMMANDS,
  },
  {
    id: "prisma",
