import { promises as fs } from "node:fs";
import path from "node:path";

export type Exclusions = {
  dirs: string[];
  files: string[];
};

export const DEFAULT_EXCLUSIONS: Exclusions = {
  dirs: [
    "node_modules",
    ".git",
    ".next",
    "dist",
    "build",
    ".turbo",
    "data/app",
  ],
  files: [".env", ".env.local", ".env.production", "package-lock.json", "pnpm-lock.yaml", "yarn.lock"],
};

const EXCLUSIONS_DIR = "data/app";
const EXCLUSIONS_FILE = "data/app/exclusions.json";

export async function loadExclusions(root: string): Promise<Exclusions> {
  const absDir = path.join(root, EXCLUSIONS_DIR);
  const absFile = path.join(root, EXCLUSIONS_FILE);

  try {
    const raw = await fs.readFile(absFile, "utf8");
    const parsed = JSON.parse(raw) as Partial<Exclusions>;
    return {
      dirs: Array.isArray(parsed.dirs) ? parsed.dirs : [],
      files: Array.isArray(parsed.files) ? parsed.files : [],
    };
  } catch {
    await fs.mkdir(absDir, { recursive: true });
    await fs.writeFile(absFile, JSON.stringify(DEFAULT_EXCLUSIONS, null, 2), "utf8");
    return DEFAULT_EXCLUSIONS;
  }
}

export async function saveExclusions(
  root: string,
  excl: Exclusions,
): Promise<void> {
  const absDir = path.join(root, EXCLUSIONS_DIR);
  const absFile = path.join(root, EXCLUSIONS_FILE);
  await fs.mkdir(absDir, { recursive: true });
  await fs.writeFile(absFile, JSON.stringify(excl, null, 2), "utf8");
}

function matchGlob(pattern: string, value: string): boolean {
  const escaped = pattern
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*\*/g, "§§")
    .replace(/\*/g, "[^/]*")
    .replace(/§§/g, ".*");
  return new RegExp(`^${escaped}$`).test(value);
}

export function isExcluded(relPath: string, excl: Exclusions): boolean {
  const normalized = relPath.replace(/\\/g, "/");

  for (const dir of excl.dirs) {
    const d = dir.replace(/\/+$/, "");
    if (normalized === d || normalized.startsWith(d + "/")) return true;
  }

  for (const file of excl.files) {
    if (matchGlob(file, normalized)) return true;
    if (normalized === file) return true;
    if (normalized.endsWith("/" + file)) return true;
  }

  return false;
}

